mapper.sql:
and (
    t.create_by = #{currentUserId}
    or exists (
        select 1 from ry_business.ry_rental_work_assignment va
        where va.tenant_id = t.tenant_id and va.member_id = t.member_id
          and va.task_id = t.task_id and va.assignee_user_id = #{currentUserId}
          and va.is_delete = 0
    )
    or (
        t.source_type = 1
        and (
            t.warehouse_id is null


                    or t.warehouse_id is not null


                    or t.warehouse_id in

                        #{warehouseId}



        )
    )
)

mapper.select:
select a.assignee_user_id as userId, count(distinct a.assignment_id) as assignedCount, count(distinct case when a.assignment_status = 3 then a.assignment_id end) as completedCount, count(distinct case when a.assignment_status in (0, 1, 2, 4) then a.assignment_id end) as pendingCount, count(distinct case when t.task_status in (0, 1, 2) and t.due_time is not null and t.due_time < date_add(#{reportDate}, interval 1 day) and a.assignment_status <> 3 then a.assignment_id end) as overdueCount, count(reviewDay.assignmentId) as scoreCount, coalesce(sum(reviewDay.scoreTotal), 0) as scoreTotal, coalesce(round(avg(reviewDay.averageScore), 2), 0) as averageScore from ry_business.ry_rental_work_assignment a inner join ry_business.ry_rental_work_task t on t.task_id = a.task_id and t.tenant_id = a.tenant_id and t.member_id = a.member_id and t.is_delete = 0 left join ( select s.assignment_id as assignmentId, avg(r.score) as averageScore, sum(r.score) as scoreTotal from ry_business.ry_rental_work_submission s inner join ry_business.ry_rental_work_review r on r.submission_id = s.submission_id and r.tenant_id = s.tenant_id and r.member_id = s.member_id and r.is_delete = 0 where s.tenant_id = #{tenantId} and s.member_id = #{memberId} and s.is_delete = 0 and r.create_time >= #{reportDate} and r.create_time < date_add(#{reportDate}, interval 1 day) group by s.assignment_id ) reviewDay on reviewDay.assignmentId = a.assignment_id where a.tenant_id = #{tenantId} and a.member_id = #{memberId} and a.is_delete = 0 and a.assigned_time >= #{reportDate} and a.assigned_time < date_add(#{reportDate}, interval 1 day)
and t.warehouse_id = #{warehouseId}
group by a.assignee_user_id order by completedCount desc, assignedCount desc, a.assignee_user_id asc
